// Must references a curated action. An invalid static registry entry is a
// programming error, caught during package initialization and registry tests.
func Must(action string) Spec {
	spec, ok := curated[action]
	if !ok {
		panic("uncurated action: " + action)
	}
	return spec
}

// Lookup returns a curated identity; generated rest.* and graphql.* names are
// deliberately not part of this catalogue.
func Lookup(action string) (Spec, bool) {
	spec, ok := curated[action]
	return spec, ok
}

// All returns every curated identity, including request-dependent actions,
// ordered by action name. The returned slice may be modified by the caller.
func All() []Spec {
	specs := make([]Spec, 0, len(curated))
	for _, spec := range curated {
		specs = append(specs, spec)
	}
	slices.SortFunc(specs, func(a, b Spec) int { return cmp.Compare(a.Action, b.Action) })
	return specs
}

// Apply changes only operation identity, preserving targets and input evidence.
func Apply(op *model.Operation, action string) {
	spec := Must(action)
	op.Family, op.Action, op.Effect = spec.Family, spec.Action, spec.Effect
}

// KnownPattern reports whether glob matches a curated action.
func KnownPattern(glob string) bool {
	for action := range curated {
		if match, _ := path.Match(glob, action); match {
			return true
		}
	}
	return false
}
